// TestDeclarationsMatchTheOfficialSamples checks the payload of every
// declaration type against the reference payload of the Ministry.
func TestDeclarationsMatchTheOfficialSamples(t *testing.T) {
	for _, sample := range declarationSamples {
		t.Run(sample.name, func(t *testing.T) {
			want := readDeclarationSample(t, sample.file)

			got, err := sample.roundTrip(want)
			if err != nil {
				t.Fatalf("the payload of %s could not be built: %v", sample.name, err)
			}

			if diff := compareFields(got, want); len(diff) > 0 {
				t.Errorf("the payload of %s does not match the official sample:\n  %s",
					sample.name, strings.Join(diff, "\n  "))
			}
		})
	}
}

// readDeclarationSample reads a reference payload and returns the fields of
// the declaration.
func readDeclarationSample(t *testing.T, name string) map[string]any {
	t.Helper()

	path := filepath.Join("testdata", "declarations", name)
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("Failed to read %s: %v", path, err)
	}

	var document map[string]any
	if err := json.Unmarshal(data, &document); err != nil {
		t.Fatalf("Failed to decode %s: %v", path, err)
	}

	for _, value := range document {
		object, ok := value.(map[string]any)
		if !ok {
			t.Fatalf("The root of %s does not hold an object", path)
		}
		for _, inner := range object {
			if list, ok := inner.([]any); ok {
				if len(list) == 0 {
					t.Fatalf("The declaration of %s is empty", path)
				}
				inner = list[0]
			}
			fields, ok := inner.(map[string]any)
			if !ok {
				t.Fatalf("The declaration of %s is not an object", path)
			}
			return fields
		}
	}

	t.Fatalf("The declaration of %s is empty", path)

	return nil
}
